      'こちら',
      'ここ',
      'こちらをクリック',
      'ここをクリック',
      'クリック',
      '詳しく',
      '詳しくは',
      '詳しくはこちら',
      '詳細',
      '詳細はこちら',
      '詳細を見る',
      'もっと見る',
      'もっと読む',
      'さらに詳しく',
      '続きを読む',
